  const save=async()=>{if(busy||!beginSaveOnce(saveInFlightRef))return;const linesGate=evaluateItemLinesGate(form.itens);if(linesGate.blockSave){endSaveOnce(saveInFlightRef);toast.error(linesGate.hint||'Corrija quantidade e preço dos itens antes de salvar.');return;}if(simulacaoDirtyGate.blockSave){endSaveOnce(saveInFlightRef);toast.error(simulacaoDirtyGate.hint||'Simule novamente antes de salvar.');return;}try{assertSimulacaoFreshForSave({simulacaoDirty,canSimular});}catch(error){endSaveOnce(saveInFlightRef);toast.error(message(error));return;}if(deliveryAddressUi.blockSave){endSaveOnce(saveInFlightRef);toast.error(deliveryAddressUi.hint||'Endereço de entrega indisponível (fail-closed).');return;}const alcada=evaluateDescontoAlcadaUi({items:form.itens,hasPermission,entity:'pedido',mode:editing?'update':'create',actorId,criadorActorId:editing?null:actorId});if(!alcada.canSave){endSaveOnce(saveInFlightRef);toast.error(alcada.hint||'Desconto acima da alçada — salvar bloqueado.');return;}const creditoSave=evaluatePedidoCreditoUiGate({groupId,empresaId,clienteEmpresaId:form.cliente_empresa_id||null,clienteId:resolveClienteIdFromEmpresaLink(masters.clientesEmpresa.find(x=>x.id===form.cliente_empresa_id))||masters.clientesEmpresa.find(x=>x.id===form.cliente_empresa_id)?.cliente_id||null,clienteEmpresa:masters.clientesEmpresa.find(x=>x.id===form.cliente_empresa_id)||null,cliente:(()=>{const link=masters.clientesEmpresa.find(x=>x.id===form.cliente_empresa_id);const row=link?clients.get(link.cliente_id):null;return row?{...row,id:row.id||link.cliente_id}:null;})(),valorPedido:Number((()=>{try{return calculatePedidoTotals(form.itens).total;}catch{return 0;}})())||0,hasPermission});if(creditoSave.blockSave){endSaveOnce(saveInFlightRef);toast.error(creditoSave.hint||'Crédito bloqueado — salvar fail-closed.');return;}setBusy(true);try{const formToSave=mergeSimulacaoBeforeSave(form,lastSimulation,{groupId,empresaId});if(formToSave!==form)setForm(formToSave);const payload=buildPedidoPayload(formToSave,{promocao:simulacaoPreview?.promocao?.aplicada?{aplicada:true,bps:simulacaoPreview.promocao.bps,cupom:promoCupom}:undefined});const saved=editing?await api.update(editing.id,payload):await api.create(payload);toast.success(editing?'Pedido atualizado.':'Pedido criado.');setSelected(saved);setEditing(saved);setForm(mapPedidoRowToForm(saved));setDirty(false);applyPersistedSnapshotsFromRow(saved);setFormOpen(true);await queryClient.invalidateQueries({queryKey:['pedidos-http',groupId,empresaId]});}catch(error){toast.error(message(error));}finally{setBusy(false);endSaveOnce(saveInFlightRef);}};
  const show=async(row)=>{try{const [detail,events]=await Promise.all([api.get(row.id),api.history(row.id)]);setSelected(detail);setHistory(events);setDetailOpen(true);}catch(error){toast.error(message(error));}};
  const transition=async(row)=>{const target=nextPedidoStatus(row);if(!target||busy)return;setBusy(true);try{const updated=await api.transition(row.id,target);setSelected(updated);setHistory(await api.history(row.id));toast.success(`Pedido movido para ${PEDIDO_STATUS_LABELS[target]}.`);await queryClient.invalidateQueries({queryKey:['pedidos-http',groupId,empresaId]});}catch(error){toast.error(message(error));}finally{setBusy(false);}};
  const requestCancel=(row)=>{if(!row||!canCancel(row)||busy)return;setPendingCancel(row);};
  const cancel=async(row)=>{if(!row||!canCancel(row)||busy)return;setBusy(true);try{const updated=await api.cancel(row.id,'Cancelamento confirmado pelo usuário');setSelected(updated);setHistory(await api.history(row.id));toast.success('Pedido cancelado e preservado.');await queryClient.invalidateQueries({queryKey:['pedidos-http',groupId,empresaId]});}catch(error){toast.error(message(error));}finally{setBusy(false);}};
  if(!canView)return <div className="w-full h-full flex items-center justify-center p-6"><Alert className="max-w-lg"><AlertCircle className="h-4 w-4"/><AlertDescription>Acesso negado aos Pedidos.</AlertDescription></Alert></div>;
  const rows=list.data?.data||[];const meta=list.data?.meta||{total:0};let localTotals={subtotal:'0',desconto:'0',total:'0'};try{localTotals=calculatePedidoTotals(form.itens);}catch{localTotals={subtotal:'0',desconto:'0',total:'0'};}const totals=resolveDisplayTotals(simulacaoPreview,localTotals);
  const creditoLink=masters.clientesEmpresa.find(x=>x.id===form.cliente_empresa_id)||null;const creditoCliente=(()=>{if(!creditoLink)return null;const row=clients.get(creditoLink.cliente_id);return row?{...row,id:row.id||creditoLink.cliente_id}:null;})();const creditoGate=evaluatePedidoCreditoUiGate({groupId,empresaId,clienteEmpresaId:form.cliente_empresa_id||null,clienteId:creditoCliente?.id||creditoLink?.cliente_id||null,clienteEmpresa:creditoLink,cliente:creditoCliente,valorPedido:Number(totals.total)||0,hasPermission});const descontoAlcada=evaluateDescontoAlcadaUi({items:form.itens,hasPermission,entity:'pedido',mode:editing?'update':'create',actorId,criadorActorId:editing?null:actorId});
  const itemLinesGate=evaluateItemLinesGate(form.itens);
